    input [3:0] in,
    output reg [1:0] pos
);
    wire [1:0] p0_pos;
    wire [1:0] p1_pos;
    wire [1:0] p2_pos;
    wire [1:0] p3_pos;
    reg [1:0] pos2;
    reg [1:0] pos3;
    reg [1:0] pos4;
    wire [1:0] p4_pos;
    priority_encoder_2_level_chain p0(.in(in[0]), .pos(p0_pos));
    priority_encoder_2_level_chain p1(.in(in[1]), .pos(p1_pos));
    priority_encoder_2_level_chain p2(.in(in[2]), .pos(p2_pos));
    priority_encoder_2_level_chain p3(.in(in[3]), .pos(p3_pos));
    priority_encoder_2_level_chain p4(.in({1'b0, p0_pos, p1_pos, p2_pos, p3_pos}), .pos(p4_pos));
    always @* begin
        if (in == 4'b0000) pos = 2'd0;
        else pos = p4_pos;
    end
